<template><div class="page"><div class="head"><div><div class="eyebrow">ACTIVITY / MY</div><h1>我的活动</h1><p>查看参与记录与获得的奖励。</p></div><a-button @click="$router.push('/activity')">活动广场</a-button></div><a-card :bordered="false" class="card"><a-list :data-source="items" :pagination="{pageSize:10}"><template #renderItem="{item}"><a-list-item><a-list-item-meta :title="'活动 #'+item.activityId" :description="'参与时间：'+String(item.joinTime||'').replace('T',' ')"/><template #extra><a-tag color="gold">+{{item.bonusPoints||0}} 积分</a-tag></template></a-list-item></template></a-list><a-empty v-if="!items.length" description="还没有参加活动"/></a-card></div></template>
<script setup>import {ref,onMounted} from 'vue';import {activityApi} from '../api';const items=ref([]);onMounted(async()=>{try{items.value=(await activityApi.my())||[]}catch(e){}})</script>
